struct Exact9401ViewerToolbar: ViewModifier {
    let manager: iOSNavigationManager
    @State private var isPresented = false
    @State private var showsProfiles = false
    @Environment(\.exact9401Workspace) private var workspace
    @Environment(\.chavrusaReaderSidebar) private var sidebar

    func body(content: Content) -> some View {
        content
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button {
                        guard workspace?.attached == true, let sidebar else { return }
                        isPresented = false
                        showsProfiles = false
                        sidebar.navigationChrome.reveal()
                        sidebar.overview.request()
                    } label: {
                        Label("כל הכרטיסיות", systemImage: "square.on.square")
                    }
                    .accessibilityIdentifier("reader-tabs-overview")
                    .disabled(workspace?.attached != true || sidebar == nil)

var body: some View {
    NavigationStack {
        TabSwitcherPageHost(
            documents: (workspace.group?.tabs ?? []).map {
                ReaderTabSwitcherDocument(id: $0.id, title: $0.session.bookTitle ?? "ספר", subtitle: $0.backend.displayName)
            },
            selectedID: workspace.activeDocumentID,
            layoutMode: tabSwitcherLayout,
            onSelect: openDocument,
            onClose: closeDocument,
            onReorder: { document, index in
                workspace.reorderDocument(document.id, to: index, manager: manager)
            },
            contextMenu: contextMenu
        )
        .overlay {
            if workspace.group?.tabs.isEmpty != false {
                ContentUnavailableView {
                    Label("אין כרטיסיות בקבוצה", systemImage: "book.closed")
                } actions: {
                    Button("פתח ספר מהספרייה") { onClose(); onOpenLibrary() }
                }
            }

private func closeDocument(_ document: ReaderTabSwitcherDocument) {
    if manager.openTabs.contains(where: { $0.id == document.id }) {
        manager.closeTab(id: document.id)
        workspace.synchronize(manager)
    } else if let group = workspace.group {
        do {
            let remaining = group.tabs.filter { $0.id != document.id }
            try workspace.store.saveTabs(
                remaining,
                activeID: group.activeTabID == document.id ? remaining.first?.id : group.activeTabID,
                groupID: group.id
            )
        } catch {
            workspace.errorMessage = error.localizedDescription
        }
    }
}

    private func removeDocument(id: UUID) {
        guard let index = documents.firstIndex(where: { $0.id == id }) else { return }
        documents.remove(at: index)
        collectionView.performBatchUpdates {
            collectionView.deleteItems(at: [IndexPath(item: index, section: 0)])
        } completion: { [weak self] _ in
            guard let self else { return }
            self.pageDelegate?.page(self, didDeleteTab: id)
        }
    }
}

extension TabSwitcherPageViewController: UICollectionViewDataSource {
    func numberOfSections(in collectionView: UICollectionView) -> Int { 1 }

    func collectionView(_ collectionView: UICollectionView, numberOfItemsInSection section: Int) -> Int {
        documents.count
    }

    func collectionView(_ collectionView: UICollectionView, cellForItemAt indexPath: IndexPath) -> UICollectionViewCell {
        let identifier = layoutMode == .grid ? TabViewGridCell.reuseIdentifier : TabViewListCell.reuseIdentifier
        guard let cell = collectionView.dequeueReusableCell(withReuseIdentifier: identifier, for: indexPath) as? TabViewCell else {
            preconditionFailure("DuckDuckGo tab switcher cell registration is invalid")
        }
        cell.delegate = self
        if documents.indices.contains(indexPath.item) {
            let document = documents[indexPath.item]
            cell.configure(document: document, isCurrent: document.id == selectedID)
            cell.accessibilityIdentifier = "tab-switcher-\(layoutMode.rawValue)-cell-\(document.id.uuidString)"
        }
